import type { Chapter, Topic } from "@/lib/study/schema";

/**
 * Databases → Functional dependencies and normal forms; File organisation and indexing; Transactions; Concurrency control.
 * Numbers from lib/study/db.ts, checked by script: minimal cover of {A→BC, B→C, A→B, AB→C} = {A→B, B→C}. ABCD with AB→C, C→D: 2NF (C→D);
 * AB→C, B→D: 1NF; ABC with AB→C, C→B: keys AB, AC, 3NF not BCNF, AC + BC lossless but loses AB→C; AB + BC with B→C lossless.
 * Index: 30,000 records of 100 B, 1024-B blocks, 9-B key, 6-B pointer: bfr 10, 3000 blocks, 68 entries per index block, sparse index
 * 45 blocks → 7 reads, dense 442 blocks → 10 reads, binary search without index 12 reads. B+ order: block 512, key 9, pointer 6, record
 * pointer 7 → p = 34, leaf 31; 1,000,000 keys with p 34 and 33 per leaf → at least 4 levels. Inserting 10..70 with max 2 keys per node
 * → 3 levels, 2 root splits. Schedules: R1(A) W2(A) R2(B) W1(B) has a cycle; R1(A) R2(A) W1(A) W2(B) R3(B) ≡ T2, T1, T3.
 * W1(A) R2(A) C2 C1 not recoverable; W1(A) R2(A) C1 C2 recoverable not cascadeless; W1(A) C1 R2(A) C2 strict.
 * TO: R1(A) W2(A) W1(A) R2(A) aborts T1; with Thomas's rule W1(A) is ignored and nothing aborts.
 */
import { decomp, mvd, hashing, logrec, mgl, validation } from "./db-c";
